-- Generated from PDF text extraction; source text is stored in nodes.content.
-- PostgreSQL schema: one row per source PDF, nodes stored as JSONB.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, original_title TEXT, document_type TEXT NOT NULL, year_bs INTEGER NOT NULL, year_ad INTEGER NOT NULL, total_pages INTEGER NOT NULL, nodes JSONB NOT NULL, source_filename TEXT NOT NULL
);

INSERT INTO legal_documents (id,title,original_title,document_type,year_bs,year_ad,total_pages,nodes,source_filename) VALUES ($CODEx53ffe8355f$doc_the_act_relating_to_children_2075_2018_2075_act_relating_to_child$CODEx53ffe8355f$,$CODExa8e6f971ea$The Act Relating to Children, 2075 (2018)$CODExa8e6f971ea$,NULL,$CODEx76f3b5a717$act$CODEx76f3b5a717$,2075,2018,39,$CODEx4d1e6fd74e$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np\nThe Act Relating to Children, 2075 (2018)\nDate of authentication:\n2075/06/02 (18 September 2018)\nAct Number 23 of the year 2075 (2018)\nAn Act Made for Amendment and Consolidation of the Laws Relating to Children\nPreamble:\nWhereas, it is expedient to make amendment and consolidation of the laws relating\nto children in order to maintain the best interests of the children, by respecting, protecting,\npromoting and fulfilling the rights of the child.\nNow, therefore, be it enacted by the Federal Parliament.", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -1", "title": "Chapter -1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title and commencement: (1) This Act may be cited as the \"Act Relating", "content": "to Children, 2075 (2018)”.\n(2) It shall come into force immediately", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions: Unless the subject or the context otherwise requires, in this Act,-", "content": "(a) \"Orphan children\" means orphan children as referred to in the\nprevailing laws.\n(b) \"Investigating authority\" means an official having authority under\nthe prevailing laws to investigate into the offence.\n(c) \"Offence\" means a criminal offence as provided by the prevailing\nlaws.\n(d) \"Children in conflict with law\" means the children accused of\ncommitting an offence, and this term also includes the children\nconvicted by the Juvenile Court for committing an offence.\n(e) \"Prescribed\" or \"as prescribed\" means prescribed or as prescribed in\nthe Rules framed under this Act.\n(f) \"Diversion\" means the act of bringing the child accused of\ncommitting an offence outside the ambit of the formal judicial\nproceedings by adopting any of the processes mentioned in Section\n29.\n1\nwww.lawcommission.gov.np\n(g) \"Observation chamber\" means an observation chamber established\npursuant to Section 22.\n(h) \"Family\" means a child's father, mother, elder brother, younger\nbrother, elder sister, younger sister, grand-father or grand-mother\nliving in an undivided family and this term also includes other\nrelative living in the undivided family.\n(i) \"Council\" means the National Child Rights Council referred to in\nSection 59.\n(j) \"Children\" means persons who have not completed the age of\neighteen years.\n(k) \"Violence against children\" means an act referred to in sub-section\n(2) of Section 66.\n(l) \"Juvenile Court\" means a juvenile court constituted in accordance\nwith sub-section (1) of Section 30 and this term also includes the\njuvenile bench constituted pursuant to sub-section (3) of the said\nSection.\n(m) \"Child pornography\" means an act to take or make video or picture\nof children showing their sex organ or making them involve in\nimaginary sexual activities, to demonstrate vulgar picture through\nnewspaper, poster, print, movie or other medium of communication,\nand this term also includes activities of production, sale, import,\nexport, collection or dissemination of such materials.\n(n) \"Child welfare authority\" means an official appointed or prescribed\npursuant to Section 61.\n(o) \"Child home\" means a child home established pursuant to Section\n52.\n(p) \"Child sexual harassment/abuse\" means an act referred to in sub-\nsection (3) of Section 66.\n(q) \"Child reform home\" means a child reform home established\npursuant to Section 43.\n(r) \"Ministry\" means the Ministry of Women, Children and Senior\nCitizens of the Government of Nepal.\n(s) \"Children in need of special protection\" means the children referred\nto in Section 48.\n2\nwww.lawcommission.gov.np\n(t) \"Guardian\" means a person or institution appointed or having an\nobligation to protect the rights and interests of the child in\naccordance with this Act or the prevailing laws, and this term also\nincludes a curator in the absence of the guardian.\n(u) \"Social service provider\" means a person referred to in Section 62.\n(v) \"Local Level\" means any Rural Municipality or Municipality.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -2", "title": "Chapter -2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Right to live: (1) Every child shall have the right to live with dignity.", "content": "(2) The Government of Nepal, Province Government and Local Level shall\ntake necessary measures required for preventive and security service including\nprevention of possible accidents, minimization of risks that may occur on the\nchildren, in order to protect the rights of the child to live and development.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Right to name, nationality and identity: (1) Every child shall have the right to", "content": "have name with own identification and birth registration.\n(2) The father or mother of a child, after his or her birth, shall give a name\nto him or her and register it according to the prevailing laws.\n(3) The mother of a child born from rape or incest that is punishable by the\nprevailing laws shall register his or her birth by mentioning only the name of the\nmother if she so wishes.\n(4) While giving name pursuant to sub-section (2), if the father or mother\nof a child is not available immediately or there is no possibility that they can be\navailable, then the child may have the name given by any other family member or\nguardian who looks after him or her.\n(5) Every child after birth may use the surname given by mutual consent of\nhis or her parents or if such consent is not available he or she may use the surname\nof his or her father after his or her name.\n(6) Notwithstanding anything contained in sub-section (5), the child, if he\nor she so wishes, may use the surname of his or her father or mother or both.\n(7) A child whose paternal identity is not known may use his or her mother's\nsurname after his or her name.\n(8) If a dispute arises regarding the surname of any child, except as proved\notherwise, it shall be deemed that the child is using his or her father's surname.\n3\nwww.lawcommission.gov.np\n(9) A child whose both father and mother are not identified may use the\nsurname given by the guardian after his or her name.\n(10) The child welfare authority shall be informed about it when the\nguardian gives the name and surname pursuant to sub-section (9).\n(11) If the name of father, mother and grand-father, grand-mother must be\nmentioned pursuant to law in any formal legal proceeding or document, in cases\nwhere the father of the child is not known, he or she may mention his or her mother\nand parents’ name and if the name of mother is also not known, mentioning that\nmatter will suffice the requirement.\n(12) The mother, father or guardian of a child shall not change his or her\nname, surname that hides the identity of the child with an intention to gain undue\nbenefits.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Right against discrimination: (1) No discrimination shall be made against any", "content": "child on grounds of religion, race, caste, tribe, sex, origin, language, culture,\nideological thought, physical or mental condition, physical disability, marital\nstatus, family status, employment, health condition, economic or social condition\nof him or her or his or her family or guardian, geographical area or similar other\nground.\n(2) No one shall discriminate between son and daughter, son and son or\ndaughter and daughter or children from ex-husband or wife or present husband or\nwife in maintenance, education or health care of children.\n(3) No one shall make any kind of discrimination between their own son,\ndaughter and adopted son, daughter.\n(4) No discrimination shall be made with regard to maintenance, education\nand health care between children born to a man and woman before and after their\nmarriage.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Right to live and meet with the parents: (1) No child shall be split or separated", "content": "from his or her father or mother without his or her will.\n(2) Notwithstanding anything contained in sub-section (1), the Juvenile\nCourt may issue an order to separate any child from his or her father or mother\nand entrust him or her to any guardian's custody for the best interests of the child,\nif necessary.\nProvided that the concerned party shall not be deprived of an opportunity\nto submit his or her explanation before issuing such an order.\n4\nwww.lawcommission.gov.np\n(3) Except for the condition where the Juvenile Court has made a restriction\nstating that it would be not in the interests of a child, the child living separately\nfrom the father or mother or both shall have the right to make direct contact or\nmeet with the father or mother regularly.\n(4) The person adopting a child shall allow the adopted child to meet,\ncontact and make correspondence with his or her biological parents.\n(5) Any person or institution responsible for alternate care shall allow the\nchildren under their care or guardianship to meet their biological parents or\nfamilies.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Right to protection: (1) Every child shall have the right to obtain proper care,", "content": "protection, maintenance, love and affection from his or her father, mother, other\nmember of family or guardian.\n(2) The parents shall have equal responsibility in relation to care,\nprotection and maintenance of their children. In cases where the parents are\ndivorced or living separately due to any other reasons, financial expenses for the\nmaintenance of their children shall be borne by both parents according to their\ncapacity.\n(3) No father, mother, other member of the family or guardian shall\nabandon or leave the child of their own or under his or her guardianship\nunattended.\n(4) Children with disabilities, war victims, displaced, under vulnerable\nconditions, or living on street shall have the right to special protection as\nprescribed from the State for their secured future.\n(5) Every child shall have the right to protection against any type of\nphysical or mental violence and torture, hatred, inhuman treatment, gender or\nuntouchability-based mistreatment, sexual harassment and exploitation that might\nbe caused by his or her father, mother, other family member or guardian, teacher\nand other person.\n(6) Every child shall have the right to protection from being exploited\neconomically and shall also be entitled to be protected from any activity which\nmay be harmful to him or her or be obstacle to his or her education or detrimental\nto his or her health, physical, mental, moral, social development.\n(7) No child shall be deployed in army, police and armed group and be used\nfor armed conflict or political purpose directly or indirectly.\n5\nwww.lawcommission.gov.np\n(8) No one shall attack, or make hindrance to the operation and\nmanagement of any school, including the place, service or facility, used for the\nbest interests of children, with any excuse at times of armed conflict or in any\nadverse situation of whatever type.\n(9) Children below fourteen years of age shall not be deployed in any risky\nwork or used as a house-servant or house-maid.\n(10) The Government of Nepal, Provincial Government and Local Level\nmay follow the necessary measures and make and implement the standards for the\nprotection of the children.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Right to participate: A child who is competent to form his or her own opinion", "content": "shall have the right to participate in the decision-making process of family,\ncommunity, school or other public institution or organization on the matters\nconcerning him or her.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Right to freedom of expression and information: (1) Every child shall have the", "content": "freedom to express his or her opinion pursuant to the prevailing laws.\n(2) Every child shall have the right to demand and receive information on\nthe subject of his or her right, interest and concern subject to the prevailing laws.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Right to open organization and assemble peacefully: (1) Every child shall have", "content": "the right to open a child club or organization or the right to assemble peacefully\nfor the protection and promotion of the rights of the child.\n(2) The provisions regarding the opening of a child club or organization\npursuant to sub-section (1) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Right to privacy: (1) Every child shall have the right to privacy regarding the", "content": "subject of his or her body, residence, property, document, data, correspondence\nand character.\n(2) No one shall do, or cause to be done the act of creation of personal\ninformation, details, photo, collection of information, publishing, printing,\ndemonstrating, sale and distributing or transmitting by any means that causes\nnegative impact on the characteristics of a child or any shame, regret or domination\nto him or her.\n(3) The details that provide the identity of a child along with the name,\nsurname, address, age, sex, family background, economic status, offence\ncommitted by, and any details regarding action, if any taken, against a child who\nis victim or accused of an offence by the Juvenile Court, police office, guardian,\n6\nwww.lawcommission.gov.np\ncaretaker, or any other body shall be kept confidential. The details of a child kept\nconfidential shall not be used elsewhere except as provided by the law.\nProvided that if such details have to be published for any study or research\nwork, only the age or sex of the child, without disclosing his or her name, surname,\naddress, other data which may reveal his or her identity and his or her family may\nbe published.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Special rights of children with disabilities: (1) Special arrangements shall be", "content": "made, as prescribed, for the children with disabilities.\n(2) Every child with disability shall have the right to determine his or her\nown honour and prestige, to promote his or her own independency, to participate\nactively in the society and to live a life with dignity.\n(3) Every child with disability shall have the right to obtain special care\nand to be assimilated in the society and to obtain the opportunity to education,\ntraining, health care, rehabilitation service, preparation for employment and\nentertainment for the development of his or her personality.\n(4) Every child with disability shall have the right to equal access and\nutilize the public services and facilities.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Right to nutrition and health: (1) Every child shall have the right to proper", "content": "nutrition, clean drinking water and the child up to two years of age shall also have\nthe right to breast feeding.\n(2) Pregnant women and children shall have the right to get necessary\nvaccination to prevent diseases and allow to utilize the physical and mental health\nservices according to the national standards, to get information about body,\nreproduction and reproductive health according to age and maturity.\n(3) Every child shall have the right to obtain free basic health service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Right to sports, entertainment and culture: (1) Every child shall have the right", "content": "to play games and participate in sports according to his or her age and interest.\n(2) Every school shall encourage the children to participate in sports at the\ntime other than study and for that purpose, provide for necessary playgrounds and\nsports materials.\n(3) Every child shall have the right to child friendly entertainment\naccording to his or her age, interest and requirement.\n7\nwww.lawcommission.gov.np\n(4) Every child shall have the right to take part in cultural activities\naccording to his or her religion, culture, custom, tradition and conscience without\ncausing any adverse effect on his or her interests.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Right to education: (1) Children below six years of age shall have the right to", "content": "learn in a proper way according to their age and level of development and to pre-\nchild development.\n(2) Every child shall have the right to acquire free and compulsory\neducation upto the basic level and free education upto the secondary level pursuant\nto the prevailing law in a child friendly environment.\n(3) Every child shall have the right to acquire education through proper\nstudy materials and teaching method according to his or her special physical and\nmental condition, pursuant to the prevailing law.\n(4) Dalit children shall have the right to acquire free education with\nscholarship pursuant to the prevailing law.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -3", "title": "Chapter -3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "16", "title": "Priority to be given for the best interests of children: (1) The officials of every", "content": "organization and institution that carries out activities related to children shall\nadopt necessary child friendly process by giving priority to the best interests of\nchildren, while doing every activity.\n(2) It shall be the responsibility of everyone to instantly help children\nwhose life is in risk.\n(3) The child welfare authority or Juvenile Court shall, while making\narrangement for a child's alternative care, separating a child from his or her parents\nor guardian, making decision on who has to take care of and maintain a child after\ndivorce between his or her father and mother shall adopt the process as prescribed\nfor the best interests of the child pursuant to this Act.\n(4) Public and private social institutions where children stay or which\nprovide services to children shall, while constructing or refurbishing the physical\nstructures, make necessary arrangement that is child friendly.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Responsibility of the family or guardian: (1) Both the father and mother shall", "content": "have equal responsibility on the child's care, maintenance and overall\ndevelopment.\n8\nwww.lawcommission.gov.np\n(2) It shall be the responsibility of every father, mother, other members of\nthe family or guardian to care, maintain and protect, to provide the opportunity for\neducation, treatment, along with personality development of, to provide\nenvironment full of love and care and to guide properly for future certainty of the\nchild.\n(3) Father, mother, other family member or guardian shall provide suitable\nenvironment for acquiring education to every child of age to join school by\nadmitting him or her to the school.\n(4) Father, mother, other member of the family or guardian shall not engage\nthe child on labour which may adversely affect his or her education, health and\nphysical or mental development.\n(5) Father, mother, other member of the family or guardian shall not leave\nthe child below six years of age alone at home or any other place or send alone\nelsewhere, without being accompanied by an adult person.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Obligation of the State: The State shall make necessary arrangement for the basic", "content": "needs including maintenance, protection, health and education of children in need\nof special protection, on the basis of the available means and resources.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Responsibility of the media sector: It shall be the responsibility of the media", "content": "sector to publish and transmit information, without violating the rights of the child\nand causing adverse effect on the interests of the child.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -4", "title": "Chapter -4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "20", "title": "Matters to be considered while dispensing the juvenile justice: A person,", "content": "official and Juvenile Court involved in dispensing juvenile justice shall take into\naccount the following matters, in the course of dispensing justice, in addition to\nthe other matters as provided elsewhere in this Act:\n(a) To take opinion of a child before making a decision that affects him\nor her,\n(b) To provide an opportunity to father, mother, other family member\nor guardian to put their opinion before making decision on the\nsubject matter associated with the interests and benefits of the child,\n9\nwww.lawcommission.gov.np\n(c) To use parlance, speak and behave according to the child’s age, level\nof intellectual development, conscience and cultural norms and\nvalues,\n(d) To use language preferred by the child and to take assistance of an\ninterpreter as required while talking to him or her.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "To take a child under control: (1) If information on an offence is received, the", "content": "investigating authority shall immediately start investigation on it. While doing\nsuch investigation, if it appears that the investigation is not possible without taking\nthe child accused of the offence under control, the investigating authority may take\nhim or her under control.\n(2) If it appears that it is no longer required to take a child under control,\nwho has been taken under control, pursuant to sub-section (1), he or she shall be\nhanded over to his or her family member or guardian or the nearest relative.\n(3) If a child is taken under control pursuant to sub-section (1), the\ninvestigating authority shall give information about it to his or her family member,\nor guardian or close relative.\n(4) The investigating authority shall not use force while taking a child\nunder control pursuant to sub-section (1).\nProvided that it shall not bar the using of minimum force required to take\nthe child under control.\n(5) The child taken under control pursuant to sub-section (1) shall, if\npossible, be referred to a child psychologist or a person working in the field of\nchildren's welfare in order to provide the required counselling service.\n(6) If the child taken under control pursuant to sub-section (1) could deviate\nhimself or herself pursuant to Section 27, the investigating authority may,\nnotwithstanding anything contained in the prevailing law, take the deposition of\nhim or her by himself or herself.\n(7) The child taken under control pursuant to sub-section (1) may be kept\nin an observation chamber with the permission of the Juvenile Court for a\nmaximum twenty-one days, not exceeding five days at a time.\n(8) Notwithstanding anything contained in sub-section (7), if the Juvenile\nCourt is of the opinion that it not reasonable to keep the child accused of offence\nin the observation chamber, having regard to the child's physical condition, age,\ncircumstances at the time of commission of the offence or condition of the\n10\nwww.lawcommission.gov.np\nobservation chamber, the Juvenile Court may make an order to investigate the case\nby entrusting such a child to his or her father, mother, other family member or\nguardian and in their absence to any social organization working in the field of\nprotection of the rights and interests of the child or child reform home on the\ncondition that the child shall make presence when the Juvenile Court so requires.\n(9) While inquiring into the child taken under control, the investigating\nauthority shall make it in the presence of his or her father, mother or guardian or\nchildren welfare authority or legal practitioner in a child friendly environment.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Provision relating to establishment of observation chamber: (1) The", "content": "Government of Nepal may establish an observation chamber for the purpose of\nkeeping a child taken under control on the charge of an offence, throughout the\nperiod of investigation.\n(2) A separate room shall be arranged in every District Police Office until\nthe observation room referred to in sub-section (1) is established.\n(3) The child taken under control for investigation shall be provided with\ncounselling by a child psychologist and psycho-social support as required.\n(4) If any member of a child’s family wishes to stay together with the child\nwho is kept in the observation chamber for assistance, the investigating authority\nmay give permission to stay together specifying the time and conditions as\nrequired.\n(5) The provisions relating to the establishment, operation, management\nand monitoring of the observation chamber shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Special provision relating to investigation and prosecution: (1)", "content": "Notwithstanding anything contained in the prevailing laws, the Government of\nNepal shall form a separate unit in order to investigate into the cases of offences\nof which children are accused.\n(2) The Government of Nepal may designate an official working at the\nDistrict Police Office, who has got training on juvenile justice, to perform that\nfunction until the separate unit is formed pursuant to sub-section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Provision relating to trial: (1) No child shall be detained in the course of trial", "content": "and no bail or guarantee shall be demanded from him or her.\n(2) Notwithstanding anything contained in sub-section (1), the Juvenile\nCourt may, for reasons to be recorded, send a child accused of an offence to the\nchild reform home during trial, in any of the following circumstances:\n11\nwww.lawcommission.gov.np\n(a) If there is adequate ground that the child's life would be in\ndanger, someone would get hurt from him or her, such a child\nwould go away or any other reason that it is not appropriate\nto put him or her elsewhere,\n(b) If it appears from the evidence available for the time being\nthat a child accused of an offence punishable by\nimprisonment for a term not exceeding three years or more\nor there is a reasonable ground to believe that he or she is an\noffender.\n(3) Except in the circumstance referred to in sub-section (2), other child\naccused of offence may be entrusted to his or her father, mother, other family\nmember or guardian, and in their absence to an institution or person working for\nthe welfare of the children on a condition that the child will be presented as and\nwhen needed.\nProvided that if the Juvenile Court deems that it is not appropriate to keep\nthe child in the reform home, taking into account the child's physical condition,\nage, circumstances at the time of commission of the offence as mentioned in sub-\nsection (2), it shall not bar the entrusting of such a child to his or her father,\nmother, other family member or guardian, and in their absence, to an institution or\nperson protecting the rights and interests of the child, by specifying the conditions\npursuant to this sub-section.\n(4) While entrusting a responsibility of a child pursuant to sub-section (3),\nthat person and the child shall be informed about the specified conditions and the\nconsequences that must be borne if they have not been followed.\n(5) If the child who is entrusted to someone pursuant to sub-section (3)\ndoes not follow the conditions specified by the juvenile court, the trial of the case\nmay be made by keeping him or her in the child reform home.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Rights of child victim: A child victim shall have the right to child friendly justice", "content": "as follows in every stage of investigation, prosecution and judicial process:\n(a) To get information on the language he or she understands,\n(b) To participate or be involved,\n(c) To keep the details of personal identification confidential,\n(d) To get recovery of the reasonable compensation from the offender,\n12\nwww.lawcommission.gov.np\nProvided that this clause shall not be considered as limiting\nthe opportunity of the victim to receive compensation from the\nState.\n(e) To get free legal aid and socio-psychological counselling service as\nrequired and to appoint a separate legal counsel if he or she so\nwishes,\n(f) To get free service of the translator, sign language expert or\ninterpreter if the victim does not understand the language used by\nthe investigating authority or Juvenile Court,\n(g) To get, free of cost, the copy of the documents including the\ndecisions and orders made by the investigating authority or Juvenile\nCourt,\n(h) To get police protection for safety against the probable threat that\nmay be caused from the offender or his or her party,\n(i) To have his or her case heard in camera,\n(j) To have the indirect presence of the defendant in the course of\nhearing of the case as required.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Rights available to child in the course of hearing: (1) A child accused of an", "content": "offence shall have the following rights, in addition to the rights mentioned in the\nprevailing law and elsewhere in this Act, in the course of investigation and hearing\nof the case:\n(a) Right to obtain information on the charge made against him or her,\nits proceeding, order issued or decision made on it directly or\nthrough his or her family or guardian,\n(b) Right to receive free legal aid and other necessary support\nimmediately in order to defend against the charge made against him\nor her,\n(c) Right to have the case tried and settled by the competent judicial\nauthority,\n(d) Right to demand the presence of family or guardian required in all\nprocesses of juvenile justice delivery,\n(e) Right to receive prompt and fair justice from the Juvenile Court,\n(f) Right to have confidentiality in the process of juvenile justice\ndelivery\n13\nwww.lawcommission.gov.np\n(g) Right to get information on the constitutional or legal rights,\n(h) Right to have investigation, prosecution and hearing in the child\nfriendly environment,\nExplanation: For the purposes of this clause, \"child friendly\nenvironment\" means the treatment done with the child that is\ncommensurate to the age, maturity and psychology of the child, this\nterm also includes the use of the language understood by the child,\ncreation of the fearless atmosphere, presence of his or her mother,\nfather or other family member or guardian, addressing the personal\nneeds of the child and the availability of the facilitator as required.\n(i) Right to have an opportunity to participate in every stage of judicial\nproceedings and to put his or her own views independently,\n(j) Right to allow the participation of the parents, guardian of the child,\nduring the hearing of the case, if he or she so wishes,\n(k) Right to stay separately from the offender, if the child so wishes\nwhere the father, mother, parents or guardian of the victim child is\nthe perpetrator.\n(2) The child accused of an offence shall be presumed to be innocent unless\ndecided otherwise by the Juvenile Court, and such child shall not be compelled to\ngive testimony against him or herself.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "To divert: (1) Notwithstanding anything contained in the prevailing laws, the", "content": "following authorities may, in the following circumstances, take decision to divert\na child accused of an offence, if it appears reasonable to divert the child for his or\nher best interests:\n(a) The investigating authority, where the claimed amount is\nupto five thousand rupees or the offence t is punishable by a\nfine of upto two thousand rupees or imprisonment for a term\nof upto two months,\n(b) The government attorney, where the claimed amount is upto\nten thousand rupees or the offence is punishable by a fine of\nupto five thousand rupees or imprisonment for a term of upto\nthree years,\n(c) The Juvenile Court, irrespective of the claimed amount or the\namount of fine or term of imprisonment.\n14\nwww.lawcommission.gov.np\n(2) Notwithstanding anything contained in clause (c) of sub-section (1), a\nchild shall not be diverted in a case punishable by imprisonment for a term of three\nyears or more than three years shall not be diverted.\n(3) The child or guardian may, if not satisfied with the order of diversion,\nfile a petition in the Juvenile Court in the case of clauses (a) and (b) of sub-section\n(1) and in the High Court in the case of clause (c).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Matters to be considered in making diversion: The following matters shall be", "content": "considered while making diversion:\n(a) Confession of offence by the child,\n(b) Consent of the concerned child, his or her father, mother and other\nfamily member, or guardian where there are no parents,\n(c) Receipt of consent of the victim ensuring the rehabilitation of the\nvictim party to the extent of possible,\n(d) Nature of the offence and circumstances of its commission, gravity\nof the event, age, maturity and intellectual level, family\nenvironment of the child and the damage caused to the victim and\nhis or her rehabilitation are to be considered.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Procedures to be followed while making diversion: (1) One or more of the", "content": "following appropriate procedures shall be followed while diverting a child, also\nhaving regard to his or her desire:\n(a) To have reconciliation or understanding between the child and the\nvictim,\n(b) To make the child realize the mistake,\n(c) To provide necessary counselling to the child and his or her family,\n(d) To send the child to any community service,\n(e) To send the child to any institution for his care and protection,\n(f) To release the child on supervision and direction of the child welfare\nauthority,\n(g) To entrust the child to his or her father, mother or other family\nmember or guardian,\n(h) To make the child participate in any training or educational\nprogram.\n(2) While diverting a child by adopting any procedure referred to in clauses\n(d), (e), (f), (g) and (h) of sub-section (1), the period shall also be fixed.\n15\nwww.lawcommission.gov.np\n(3) While diverting a child by adopting the procedure referred to in clauses\n(d), (e), and (f) of sub-section (1), no diversion shall be made so that it exceeds\nthe maximum term of punishment imposable for the commission of the offence.\n(4) The investigating authority or government attorney shall, before\ndiverting a child, obtain a report on study and analysis of physical and mental\ncondition of the child by the child psychologist and child expert and economic,\ncultural condition and circumstances of the child by the social worker.\n(5) The investigating authority, government attorney or Juvenile Court\nshall give the information about the diversion of the child pursuant to sub-section\n(1) to their respective higher office and Juvenile Court.\n(6) If the child accused of an offence is diverted, such a dispute shall\nterminate, and its formal judicial proceeding shall be deemed to be concluded.\n(7) The investigating authority, government attorney or Juvenile Court that\nhas made diversion shall make arrangement to monitor, whether the diverted child\nhas been continuously participating in the diversion procedure or not, through a\nprobation officer.\n(8) The following may be done to indemnify the damage caused to the\nvictim while diverting a child:\n(a) To compensate the victim or to have recovery of the actual loss and\ndamage,\n(b) To cause the property, profit or material acquired from the offence\nto be returned to the concerned owner,\n(9) Other provisions relating to the diversion shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Formation of the Juvenile Court: (1) The Government of Nepal may, on", "content": "recommendation of the Judicial Council, form the required number of Juvenile\nCourts to originally proceed, try and settle the offence committed by the children.\n(2) The notice of formation of the Juvenile Courts pursuant to sub-section\n(1) shall be published in the Nepal Gazette, and the territorial jurisdiction and\nvenue of such Courts shall be as mentioned in the same notice.\n(3) A juvenile bench shall be formed in each District Court for the\nproceeding, hearing and settlement of the offence to be dealt with the juvenile\ncourt until the Juvenile Court is formed under sub-section (1).\n(4) The juvenile bench referred to in sub-section (1) shall consist of the\nfollowing members:\n16\nwww.lawcommission.gov.np\n(a) District Judge,\n(b) Social service provider,\n(c) Child psychologist or child specialist.\n(5) The qualification, appointment, remuneration and other conditions of\nservice of the social service provider, child psychologist or child specialist\nreferred to in clauses (b) and (c) of sub-section (4) shall be as prescribed.\n(6) Notwithstanding anything contained in sub-section (1), if an adult\nperson is involved, along with the child, in any offence, the matter shall be\nproceeded, tried and settled by the Juvenile Court in the case of the child, and the\nmatter shall be proceeded, tried and settled pursuant to the prevailing laws in the\ncase of the adult person by establishing a separate case file.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Exercise of jurisdiction of the Juvenile Court: The exercise of jurisdiction of", "content": "the Juvenile Court shall be made as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Proceeding by the Juvenile Court: Even if the child attains the age of eighteen", "content": "years during the proceeding of the case, such case shall be proceeded, tried and\nsettled by the Juvenile Court itself.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Cases to be transferred to the Juvenile Court: If any child has been accused of", "content": "offence before the commencement of this Act and the case is being originally tried\nby the District Court or other body pursuant to the prevailing laws, the case shall\nbe transferred to the concerned Juvenile Court after the commencement of this\nAct.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Provision relating to trial: (1) The Juvenile Court shall try the case in a child", "content": "friendly environment by taking into consideration the age and maturity of the\nchild.\n(2) The Juvenile Court shall make the child participate while trying the\ncase and shall provide an opportunity to freely put his or her views.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "Provision of in camera bench: (1) The trial and adjudication of the case against", "content": "a child accused of an offence shall be carried out in camera bench except as\notherwise ordered by the Juvenile Court.\n(2) During the trial and adjudication of the case in-camera pursuant to sub-\nsection (1), only the concerned child, his or her family member or guardian,\nvictim, government attorney, concerned legal practitioner and the person\npermitted by the Juvenile Court may enter into the in-camera bench.\n(3) The procedures of the in-camera bench shall be as prescribed.\n17\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Provisions relating to punishment: (1) If the child is less than ten years of age", "content": "at the time of commission of the offence, no case and punishment of any kind shall\nbe instituted against and imposed on him or her.\n(2) If a child of ten years of age or above but below fourteen years of age\ncommits an offence that is punishable by a fine, the child shall be released after\ncounseling him or her and if such a child commits an offence that is punishable by\nimprisonment, the child shall be punished with imprisonment for upto six months\nor be sent to the child reform home for a period not exceeding one year without\nsubjecting him or her to imprisonment.\n(3) If a child of fourteen years of age or above but below sixteen years of\nage commits an offence, the child shall be punished with half the punishment that\nis imposable on the person having attained majority pursuant to the prevailing law.\n(4) If a child of sixteen years of age or above but below eighteen years of\nage commits an offence, the child shall be punished with two-thirds of the\npunishment that is imposable on the person of legal age pursuant to the prevailing\nlaw.\n(5) The Juvenile Court shall, having regard, inter alia, to the age, sex,\nmaturity of the child who is held to be subject to punishment pursuant to sub-\nsection (2), (3) or (4), nature of the offence and also the circumstances of the\ncommission of the offence, postpone his or her punishment or make any of\nfollowing appropriate decisions as punishment, with or without specifying the\nterms and conditions:\n(a) To counsel or advise the child about good human behaviours\nby any family member or guardian,\n(b) To give orientation to the child through any institution or\nperson that provides the service,\n(c) To provide single, group or family psycho-social counselling\nservice,\n(d) To keep the child under the observation of any family\nmember, guardian, school, person or institution that provides\nservice for a fixed period subject to the observance of the\nspecified terms and conditions,\n(e) To send the child for community service that is suitable to\nhis or her age, by specifying the nature and period of service,\n18\nwww.lawcommission.gov.np\n(f) To make the child stay in the child reform home for a period\nnot exceeding that of the punishment imposed on him or her.\n(6) If any person has caused a child to commit an offence, by teaching,\ngiving pressure, ordering, luring or in any other manner, that person who has\ntaught so, given pressure, ordered, lured or made to commit it shall be punished\npursuant to law as if that person committed the offence on his or her own.\n(7) Notwithstanding anything contained elsewhere in this Section, while\npunishing a child who has not completed sixteen years of age, no punishment of\nimprisonment shall be imposed on such a child except in cases where he or she\nhas committed a heinous offence, grave offence or repeated the offence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "Period for disposing of the case: Notwithstanding anything contained in the", "content": "prevailing laws, the Juvenile Court shall generally dispose of a case within one\nhundred twenty days from the date of filing of the case and the proceeding and\nadjudication of such a case shall be made on the basis of continuous hearing.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "Reform period may be reduced or remitted: (1) If there is satisfactory", "content": "improvement in the behaviour of a child kept in the child reform home or kept\nunder the protection or supervision of any institution or person pursuant to the\ndecision of the Juvenile Court, the child welfare authority may recommend the\nJuvenile Court to reduce or remit the period of reform of such a child.\n(2) The Juvenile Court may reduce or remit the remaining period of reform\nof the child if it thinks it reasonable to reduce or remit the period of reform upon\nexamining the recommendation received pursuant to sub-section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "Restorative justice: (1) While dispensing the juvenile justice, it shall be made in", "content": "compliance with the principle of restorative justice.\n(2) Other provisions relating to restorative justice shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "40", "title": "Not to be considered disqualified: Notwithstanding anything contained in the", "content": "prevailing laws, if any person becomes disqualified to receive any post or facility\npursuant to law by the reason of the commission by him or her of any offence, he\nor she shall not be considered disqualified to receive that post or facility on the\nground of the offence that he or she committed when he or she was a child.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "41", "title": "Punishment not to be counted: (1) Notwithstanding anything contained in the", "content": "prevailing laws, the offence committed by a person during childhood shall not be\ncounted while counting repeated offence pursuant to this Act or the prevailing\nlaws, for the purposes of punishment.\n19\nwww.lawcommission.gov.np\n(2) Notwithstanding anything contained in the prevailing laws, although\nany child commits an offence time and again, he or she shall not be subjected to\nadditional punishment on the basis of repetition of the commission of the offence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Not to be handcuffed, shackled or kept in solitary confinement:", "content": "Notwithstanding anything contained in the prevailing laws, no child in conflict\nwith law shall be handcuffed, shackled or kept in solitary confinement or\ndetention, or prison.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Provision relating to child reform home: (1) The Government of Nepal shall", "content": "establish the child reform home as required for the purpose of keeping the children\nin conflict with law until their reform and rehabilitation.\n(2) Any institution may, with the approval of the Government of Nepal,\nestablish a child reform home, for the purpose of sub-section (1).\n(3) The Juvenile Court may monitor and inspect the child reform homes\nestablished within its territorial jurisdiction, issue necessary directives to such\nchild reform homes and order such child reform homes to submit reports on the\ncondition of reform of the children kept in such homes.\n(4) If a child kept in a child reform home attains the age of eighteen years\nbefore completion of the period for which he or she has to remain in the child\nreform home, he or she shall be kept separately from the other children in the child\nreform home for the remaining period by considering, inter alia, the improvement\nseen in his or her behaviour, continuity of skills and education gained.\n(5) The establishment, operation, monitoring and other arrangement of the\nchild reform home shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "To shift children suffering from chronic or serious disease to another place:", "content": "(1) If any child kept in a child reform home needs continuous treatment because\nhe or she has suffered from any chronic or serious disease or if the concerned\ndoctor has recommended to shift any child somewhere else due to his or her\nphysical or mental disability or his or her addiction to narcotics, the Juvenile Court\nmay issue an order to shift such a child to another place for a certain period.\n(2) An institution or person who keeps the child as per the order issued\npursuant to sub-section (1) shall submit a report related to the health of the child\nto the concerned Juvenile Court in every six months.\n20\nwww.lawcommission.gov.np\n(3) If the child is found to be healthy or free from addiction on the basis of\nthe report referred to in sub-section (2), the Juvenile Court may issue an order to\nreturn that child to his or her previous condition.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Psycho-sociological and psychological study report: (1) An individual psycho-", "content": "sociological and psychological study report shall be prepared for the purpose of\ninvestigation, prosecution, proceeding, hearing or adjudication of the charge made\nagainst a child in conflict with law.\n(2) The provisions regarding the preparation of the study report referred to\nin sub-section (1) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "Central Juvenile Justice Committee: (1) There shall be a Central Juvenile", "content": "Justice Committee, as prescribed, at the central level for carrying out the functions,\nincluding making coordination between the various institutions working in the\nfield related to juvenile justice.\n(2) The meetings, functions, duties and powers of the Central Juvenile\nJustice Committee shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "47", "title": "District Juvenile Justice Committee: (1) There shall be a District Juvenile", "content": "Justice Committee in every district, and the formation, functions, duties and\npowers and rules of procedures of meetings of such Juvenile Justice Committee\nshall be as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "CHAPTER 5", "title": "CHAPTER 5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "48", "title": "Children in need of special protection: (1) The following children shall be", "content": "deemed to be children in need of special protection:\n(a) Orphan children,\n(b) Children that have been left or found abandoned in hospitals or other\npublic places or separated from parents or left unclaimed, with the\nidentity of their parents unknown,\n(c) Children that are deprived of appropriate care due to serious\nphysical or mental disability or incapacity of their parents,\n(d) Out of the children in conflict with law, those who have been\nreferred for alternative care under the diversion process,\n(e) Children who are staying in prison being dependent on their father\nor mother who is detained or imprisoned,\n21\nwww.lawcommission.gov.np\n(f) Infants born due to rape or incestuous relationships that are\npunishable by law and concerning whom application has been made\nto the child welfare authority, stating inability to maintain them,\n(g) Children who have been separated from their families for their best\ninterests due to abuse, violence or neglect by their respective father,\nmother or guardian,\n(h) Children who are earning their living by engaging in labour that is\nforced or bonded or hazardous or worst in form or that contravenes\na prevailing law, who are addicted to smoking, drinking or other\nnarcotic drugs, or are infected with HIV,\n(i) Children who are experiencing difficulty leading normal life or\nwhose lives are at risk, having been suffering from serious physical\nor mental health problems or serious disability, due to the inability\nof their parents or families to afford treatment,\n(j) Children who are the victims of offences against children or are at\nsuch risks,\n(k) Children who have lost both or either of their parents, or whose\nparents have disappeared, or have themselves got injured physically\nor mentally or disability due to a disaster or armed conflict,\n(l) Children belonging to deprived Dalit communities,\n(m) Such other children as may be specified as children in need of\nspecial protection by the Ministry by publishing a notice in the\nNepal Gazette.\n(2) Other services and support, including rescue, temporary protection,\nhealth treatment, psychosocial support, family reunion, rehabilitation, alternative\ncare, family support, social security and socialization, as required, to children\nreferred to in subsection (1) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "49", "title": "Provision of alternative care: (1) The children referred to in clauses (a), (b), (c),", "content": "(d), (e), (f) and (g) shall be considered as children that require alternative care.\n(2) The child welfare authority shall make arrangements for alternative care\nfor the children referred to in sub-section (1) on the basis of the following order\nof priority:\n(a) Relative from the side of the father or mother of the child,\n(b) Family or person willing to provide care to the child,\n22\nwww.lawcommission.gov.np\n(c) Organization that provides foster (family-modelled) care,\n(e) Children’s home.\n(3) Other provisions relating to alternative care shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "50", "title": "Protection of children: (1) A person who has information about a child in need", "content": "of special protection at any place shall give information thereof to the child welfare\nauthority.\n(2) If information is received pursuant to sub-section (1), the child welfare\nauthority shall, if he or she finds it necessary to urgently rescue the child, rescue\nthe child and keep him or her in a temporary protection service referred to in\nSection 69.\n(3) The child welfare authority may make arrangements for providing\nnecessary services, upon conducting inquiry on the basis of the information\nreceived pursuant to sub-section (1).\n(4) The child welfare authority may entrust a social service provider in\norder to provide necessary services pursuant to sub-section (3), as prescribed.\n(5) While conducting inquiry pursuant to sub-section (3), other services\nneeded by the children in need of special protection shall be ensured. If it is\ndeemed that special protection is not necessary and the child’s father, mother,\nother family member or guardian has been traced, the child welfare authority may\nhand over the custody of such children to them.\n(6) If the child welfare authority thinks that any support is needed for\nhanding over the custody of the child to her or his father, mother, other family\nmember or guardian pursuant to sub-section (5), he or she shall make arrangements\nfor necessary services such as sponsorship or family support, by making\ncoordination with the relevant organizations.\nClarification: For the purposes of this Section:\n(a) “Sponsorship” means the act of making available financial support\non the long-term or short-term basis for necessary maintenance and\neducation for children by any person, organization or body.\n(b) “Familial support” means the support provided for creating an\nenvironment that is conducive to safeguarding of children within the\nfamily by identifying and addressing the economic and social\nfactors that lead the child’s family to disintegration, while\nmaintaining unity and harmony in the family.\n23\nwww.lawcommission.gov.np\n(7) If, in making examination and inquiry pursuant to sub-section (3), it\nappears that alternative care is necessary, the child welfare authority shall make\narrangements for such care.\n(8) In a case involving a child as a victim, the child welfare authority shall\narrange for separating a child victim from her or his parents or family and keep\nhim or her in a temporary protection service for a certain period of time, if the\nchild so desires, or the parent or guardian is the perpetrator or because of their\ncomplicity with the perpetrator there is a possibility of greater risk to the child, or\nthere is likelihood of obstruction in the examination, inquiry, proceedings and\nfact-finding of the incident.\n(9) If, in spite of making examination and inquiry pursuant to sub-section\n(3), the paternity and maternity of the child cannot be determined, the child welfare\nauthority shall recommend for her or his birth registration and government identity\ncard setting out the identity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "51", "title": "To appoint or designate guardian: In providing the alternative care service", "content": "pursuant to Section 49, arrangement shall be made for appointing or designating a\nguardian pursuant to the prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "52", "title": "Establishment and operation of children’s home: (1) The Government of Nepal,", "content": "Provincial Government and the Local Level shall establish children’s homes, as\nrequired, for the purpose of protection of the children requiring special protection.\n(2) The provisions relating to the establishment of children’s home,\nqualifications of operators, operational licence, renewal, classification,\nmanagement, operation standards and monitoring shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "53", "title": "Duration of stay at children’s home: The children requiring special protection", "content": "shall be kept in children’s homes until they have been properly rehabilitated or\nuntil they have attained the age of eighteen years.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "54", "title": "Family reunion to be made: (1) Family reunion shall be made if the parents or", "content": "guardians of the children staying in children’s homes are traced and it is in the\nbest interests of the children to do so.\n(2) After the commencement of this Act, no child shall be kept in a\nchildren’s home except as in accordance with Sections 49 and 69.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "55", "title": "Liability relating to rehabilitation and social reintegration: It shall be the", "content": "liability of the concerned children’s home or child correction home to assist the\n24\nwww.lawcommission.gov.np\nchild welfare authority in the rehabilitation and social reintegration of the children\nstaying at that children’s home or child correction home.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "56", "title": "Chief of the organization to be responsible: (1) If an organization is entrusted", "content": "with the guardianship of a child pursuant to this Chapter, the chief of the\norganization shall be deemed to have the ultimate responsibility for the care and\nmaintenance of the child.\nClarification: For the purposes of this Section, “chief of the organization”\nmeans the chief executive officer or chairperson, managing director of such an\norganization acting in that capacity or such other officer as designated pursuant to\nthe rules of that organization.\n(2) If any organization that has been entrusted with the responsibility of\nguardianship acts in contravention of the prescribed conditions and procedures,\nthe child welfare authority may prevent the organization from engaging in child\nprotection activities, also setting out the conditions breached by it.\n(3) If it is established from the monitoring that an organization that has\nbeen prevented pursuant to sub-section (2) has made desired improvements, the\nchild welfare authority may remove the prevention made on the organization from\nengaging in child protection activities.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "57", "title": "Standards relating to child protection: (1) A school, every public body, private", "content": "sector as well as social organization directly working with children shall formulate\nand enforce child protection standards at the institutional level, in order to prevent\nviolence against children or child sexual abuse, ensure protection of children and\nimmediately take action on complaints.\n(2) It shall be the liability of the school, chief of every public body, private\nsector and social organization to enforce the child protection standards formulated\npursuant to sub-section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "58", "title": "Monitoring and reporting: (1) The person, guardian or organization that has", "content": "assumed the responsibility of care and maintenance of children pursuant to this\nAct shall submit details of the children to the Local Child Rights Committee\nthrough the Child Welfare Authority concerned, within three weeks of the\nexpiration of each fiscal year.\n(2) Based on the details received pursuant to sub-section (1), the Local\nChild Rights Committee shall prepare and submit a report to the Provincial level\n25\nwww.lawcommission.gov.np\nChild Rights Committee and Local Level Child Rights Committee on an annual\nbasis.\n(3) The Provincial Child Rights Committee and Local Child Rights\nCommittee shall periodically inspect and monitor the overall status of children and\nthe quality and effectiveness of the available services within the Province and the\nLocal Level, respectively.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter- 6", "title": "Chapter- 6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "59", "title": "National Child Rights Council: (1) There shall be a National Child Rights", "content": "Council, as prescribed, under the chairpersonship of the Government of Nepal,\nMinister for Women, Children and Senior Citizens, in order to protect and promote\nthe rights and interests of the child.\n(2) The provisions relating to the meeting, functions, duties and powers of\nthe Council shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "60", "title": "Provincial and Local Level Child Rights Committee: (1) There shall be a", "content": "Provincial Child Rights Committee in each Province, to be chaired by the Minister\nof the Province overseeing the matters relating to children.\n(2) There shall be a Local Child Rights Committee in each Local Level, to\nbe chaired by a Member of the Rural Municipality or Municipality designated by\nthe Vice-Chairperson or Deputy-Mayor of such Rural Municipal Executive or\nMunicipal Executive respectively.\n(3) The number of members of the Provincial Child Rights Committee and\nLocal Child Rights Committee referred to in sub-sections (1) and (2), and the\nfunctions, duties and rights and procedures of meetings of the Committees shall\nbe as determined by the Province and Local Level.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "61", "title": "Child welfare authority: (1) There shall be a child welfare authority at the Local", "content": "Level in order to, inter alia, respect, protect and promote the rights of the child to\ncarry out child protection acts.\n(2) Other provisions including the appointment, functions, duties and\npowers and the terms of service of the child welfare authority shall be as\nprescribed.\n26\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "62", "title": "Social service provider and child psychologist: (1) Any persons willing to work", "content": "as social service providers and child psychologists shall get their names enlisted\nthemselves with the Local Child Rights Committee, as prescribed.\n(2) Social service providers and child psychologists may be appointed in\nrequired number, from among the social service providers and child psychologists\nenlisted in the list referred to in sub-section (1), for carrying out child protection\nrelated acts and delivering services at the Local Level.\n(3) The social service providers and child psychologists appointed pursuant\nto sub-section (2) shall act under the direct guidance and supervision of the child\nwelfare authority.\n(4) The social service providers and child psychologists required for the\njuvenile court shall be appointed from among the social service providers and child\npsychologists enlisted pursuant to sub-section (1).\n(5) The process of appointment, qualifications, functions, duties, powers,\nterms of service and other provisions related to social service providers and child\npsychologists shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "63", "title": "Child Fund: (1) There shall be a child fund, also for performing acts such as", "content": "immediate rescue, relief and rehabilitation and providing compensation to\nchildren.\n(2) The fund referred to in sub-section (1) shall consist of the following\namounts:\n(a) Amounts received from the Government of Nepal, Provincial\nGovernment and Local Level,\n(b) Amounts received from a foreign government, international agency,\norganization or individual,\n(c) Amounts received from a native person, agency or organization,\n(d) Amounts received in lieu of fines imposed by the juvenile court,\n(e) Amounts received from any other source.\n(3) The permission of the Government of Nepal, Ministry of Finance shall\nbe obtained prior to receiving amounts pursuant to clause (b) of sub-section (2).\n(4) The amounts of the fund referred to in sub-section (1) may also be made\navailable to the children's fund of the Province and Local Level in accordance with\nlaw.\n27\nwww.lawcommission.gov.np\n(5) The provisions relating to the management, operation and use of the\nfund referred to in sub-section (1) shall be as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 7", "title": "Chapter 7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "64", "title": "Local Level to enforce the rights of the child: (1) If a person violates the rights", "content": "of a child referred to in Chapter 2 or does not fulfil his or her liabilities towards\nthe child referred to in Chapter 3, the concerned child or the stakeholder may file\nan application with the judicial committee of the Local Level where the child is\nresiding, for the enforcement of such rights or liabilities.\n(2) If an application is received pursuant to sub-section (1), the judicial\ncommittee may require the person concerned to appear within twenty-four hours,\nexcluding the time required for journey, and make necessary inquiry.\n(3) If, in making inquiry pursuant to sub-section (2), it appears that the\nperson concerned has violated the rights of the child or has not fulfilled her or his\nliabilities towards the child, the judicial committee shall, within thirty days of the\nreceipt of the application, order the person, organization or agency concerned at\nthe Local Level to enforce the rights of the child or fulfil the liabilities towards\nthe child.\n(4) If, in making inquiry pursuant to sub-section (2), it appears that the\nmatter of enforcing the rights of the child or fulfilment of the liabilities towards\nthe child does not fall under its jurisdiction, the judicial committee shall write to\nthe judicial committee of the other Local Level concerned to enforce the rights of\nthe child or fulfil the liabilities towards the child.\n(5) If a correspondence is received pursuant to sub-section (4), the judicial\ncommittee of the Local Level concerned shall make arrangements to enforce the\nrights of the child and fulfilment of the liabilities towards the child pursuant to\nsub-section (3).\n(6) While enforcing the rights of the child or fulfilment of the liabilities\ntowards the child pursuant to this Section, the judicial committee may give\nnecessary suggestions to the child, guardian or family member or warning to the\nguardian or family member.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "To enforce the rights of the child: (1) Notwithstanding anything contained in", "content": "Section 64, if a person violates the rights of the child referred to in Chapter-2 or\n28\nwww.lawcommission.gov.np\ndoes not fulfil the liabilities towards the child referred to in Chapter-3, the\nconcerned child or stakeholder may file an application directly to the concerned\nHigh Court to have the said rights enforced or the said liabilities fulfilled.\n(2) If an application is received pursuant to sub-section (1), the High Court\nshall make necessary inquiry into the application and make an appropriate order\nto the person, organization or agency concerned to enforce the rights of the child\nor fulfil the duties towards the child.\n(3) If, in making inquiry into the application received pursuant to sub-\nsection (1), it appears that the guardian or family member has violated the rights\nof the child or has not fulfilled his or her liabilities towards the child, the High\nCourt shall inform such a guardian or family member about the rights of the child\nand have him or her make commitment to not to repeat the violation of the rights\nof the child or to fulfil his or her liabilities towards the child.\n(4) While making an order pursuant to sub-section (2), the High Court may\nwarn the person or chief of the organization or agency that has violated the rights\nof the child or has not fulfilled their duties towards the child or to impose\npunishment on them and order the recovery of compensation from them pursuant\nto this Act.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 8", "title": "Chapter 8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "66", "title": "Offences against the child: (1) If any person does any act of violence referred to", "content": "in sub-section (2) or sexual abuse referred to in sub-section (3), he or she shall be\ndeemed to have committed the offence against the child under this Act.\n(2) If any person does any of the following acts against a child, he or she\nshall be deemed to have committed the act of violence against the child:\n(a) To involve the child in addictions such as smoking, drinking or\ngambling,\n(b) To allow him or her to enter to, or use him or her in, recreational\nfacilities opened for the adults such as dance bars and casinos,\n(c) To show him or her motion pictures or other audio-visual materials\nclassified as for the adults only,\n29\nwww.lawcommission.gov.np\n(d) To inflict physical or mental punishment on, or behave, in an\nundignified manner, him or her whether at home, school or any other\nplace,\n(e) To inflict physical injuries or effect to, terrorize or intimidate,\nhumiliate, neglect, discriminate, exclude or hate, isolate, or cause\nmental torture to, him or her,\n(f) To harass, cause pain to, him or her by using electronic or other\nmeans,\n(g) To organize him or her for the political purpose or use him or her in\na strike, shutdown, transportation strike, sit-ins or rally,\n(h) To keep him or her in illegal confinement, detention, prison or house\narrest, handcuff him or her,\n(i) To treat him or her in a cruel or inhumane manner or torture him or\nher,\n(j) To cause him or her to beg or disguise as an ascetic, monk or\nmendicant, except for the tradition, custom or any religious or\ncultural activity,\n(k) To forcibly declare, or register him or her, as an orphan,\n(l) To offer or dedicate him or her in the pretext of a pledge, religious\nor any other purpose, or subject him or her to violence,\ndiscrimination, neglect or exclusion or mockery in the pretext of the\ncustom, culture or ritual,\n(m) To engage him or her in a magic or circus show,\n(n) To teach or train him or her to commit any offense or involve him\nor her in such offense,\n(o) To fix his or her marriage, or marry, or cause to marry, him or her,\n(p) To remove any organ of him or her in contravention of the prevailing\nlaw,\n(q) To use him or her for medical or any other experiment,\n(r) To keep him or her in a children’s home, except in accordance with\nlaw.\n(3) If any person does any of the following acts against a child, he or she\nshall be deemed to have committed child sexual abuse:\n30\nwww.lawcommission.gov.np\n(a) To show, or cause to show, him or her an obscene picture, audio-\nvisual recording or other material of similar kind or display, or cause\nto display, such expression or gesture that reflects obscene or sexual\nconduct or behaviour to him or her or display, or cause to display,\nchild pornography,\n(b) To distribute, store or use any actual or fictitious obscene picture or\naudio-visual material of him or her,\n(c) To propose, lure, coerce or threaten him or her for sexual activity,\n(d) To use him or her in the production of an obscene act and material,\n(e) To touch, kiss, hold sensitive parts of body of him or her, embrace\nhim or her with sexual intent or cause him or her to touch or hold\nsensitive parts of own body or body of another person or render him\nor her unconscious with sexual intent or display, or cause him or her\nto display sexual organs,\n(f) To use, or cause to use, him or her for stimulating sexual lust or\nsexual excitement,\n(g) To use, or cause to use, him or her for the purpose of sexual\ngratification,\n(h) To engage, or cause to engage, in child sexual exploitation,\n(i) To use, or cause to use, him or her with the intent of providing\nsexual services,\n(j) To use, or cause to use, him or her with the intent of engaging in\nsexual abuse,\n(k) To use him or her in prostitution or other sexual work.\n(4) Notwithstanding anything contained in sub-section (3), anything that is\nexpressed by means of writing, speaking, gesturing or displaying any word,\npicture, audio, visual means and object or material on a sex related matter without\ndisplaying obscenity with the aim of imparting information and education or an\nact done in good faith in the course of making treatment of the child or saving the\nchild from an accident or risk shall not be deemed to constitute an act of sexual\nabuse.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "67", "title": "Not to be deemed eligible: (1) If it is held that a person who is serving in any", "content": "public or private organization commits any offence against the child, the person\nshall be dismissed in accordance with the prevailing law, and, based on the gravity\n31\nwww.lawcommission.gov.np\nand nature of the offence, such a person shall not be deemed eligible for up to ten\nyears to be involved in the future in any act involving direct contact with the child\nor to be appointed, nominated or elected to such a private institution or\norganization.\n(2) A person who is convicted of child sexual abuse pursuant to this Act or\nthe prevailing law shall be deemed to have committed a criminal offence involving\nmoral turpitude.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "68", "title": "To give information: (1) If the father, mother, guardian, one who directly", "content": "provides services to the child such the caregiver, teacher, health-worker or any\nother person comes to know that any person has committed or is committing or\ngoing to commit act of violence or child sexual abuse against the child he or she\nshall give information thereof to the nearby police office immediately.\n(2) The police office concerned shall immediately give the information\nreferred to in sub-section (1) to the child welfare authority and seek necessary\nsupport.\n(3) While giving information with the intent of protecting the child, no legal\naction shall be taken against the informant merely on the basis that he or she has\ngiven such information.\n(4) The identity of the informant who gives information pursuant to sub-\nsection (1) shall be kept confidential if he or she so desires.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "69", "title": "Temporary protection service: The Government of Nepal shall make", "content": "arrangements for temporary protection service for safe accommodation of the\nchildren who appear to be in need of immediate rescue and protection.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "70", "title": "Rescue, protection and health check-up to be made: (1) If the police employee", "content": "receives any information, complaint or report about violence against the child or\nchild sexual abuse, he or she shall write, or cause to write, necessary details and\nregister it, and if the child needs to be rescued immediately, rescue him or her and\nrefer the victim child to a temporary protection service.\n(2) If it appears that the child victim is in physical or mental pain, the police\nemployee shall send him or her to a nearby hospital or health centre and have his\nor her health checked up and treated.\n(3) While taking the statement of the child victim, the police employee shall\ndo so in the presence of his or her parents, other family member or guardian if it\n32\nwww.lawcommission.gov.np\nis possible that they can so appear, and if they cannot so appear, in the presence\nof a female representative of a social organization or a social service provider.\nProvided that if the parents, guardian or other family members are the\nperpetrator of violence against children or child sexual abuse, their presence shall\nnot be allowed during the taking of such statement.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "71", "title": "Rehabilitation centre: (1) The Government of Nepal shall establish rehabilitation", "content": "centres, as required, for physical or mental treatment or social rehabilitation of the\nchild victims of offences against the child.\n(2) An organization may, for the purposes of sub-section (1), establish a\nrehabilitation centre by obtaining permission from the Government of Nepal as\nprescribed.\n(3) The services and facilities to be made available at the rehabilitation\ncentres and other provisions including those relating to the management,\noperation, monitoring of such centres shall be as prescribed.\n33\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-9", "title": "Chapter-9", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "72", "title": "Punishment: (1) If any person, organization or body violates any of the child", "content": "rights set forth in Chapter-2 or does not fulfil any of the liabilities towards the\nchild set forth in Chapter-3, such a person or the chief of such organization or\nbody shall be liable to a fine of up to fifty thousand rupees.\n(2) If the guardian or any family member does not fulfil his or her liabilities\nor if the mother, father or guardian alters the name and surname of the child with\nthe intention of acquiring undue benefits or misappropriates the child’s property,\nsuch a mother, father or family member or guardian shall be liable to a fine of up\nto one hundred thousand rupees.\n(3) A person who commits the offence against the child shall be liable to\nthe following punishment, according to the degree of the offence:\n(a) In the case of the commission of any act referred to in clause (a),\n(b), (c), (d), (e), (f) or (r) of sub-section (2) of Section 66 or sub-\nsection (1) or (2) of Section 78, a fine of up to fifty thousand rupees\nand imprisonment for up to one year,\n(b) In the case of the commission of any act referred to in clause (g),\n(j), (k), (l), (m), (o) or (q) of sub-section (2) of, or clause (a), (b),\n(c), (e), (f) or (i) of sub-section (3) of, Section 66, a fine of up to\nseventy-five thousand rupees and imprisonment for up to three\nyears,\n(c) In the case of the commission of any act referred to in clause (d) of\nsub-section (3) of Section 66, a fine of up to eighty thousand rupees\nand imprisonment for up to four years,\n(d) In the case of the commission of any act referred to in clause (h) or\n(i) of sub-section (2) of Section 66, a fine of up to one hundred\nthousand rupees and imprisonment for up to five years,\n(e) In the case of the commission of any act referred to in clause (n) of\nsub-section (2) of Section 66, half the punishment that is imposable\non the liable to the offender of the offence that is taught or trained\nto be committed,\n34\nwww.lawcommission.gov.np\n(f) In the case of the commission of any act referred to in clause (p) of\nsub-section (2) of Section 66, a fine of up to five hundred thousand\nrupees and imprisonment for up to ten years,\n(g) In case of an act as per clause (g) or (h) of Sub-section (3) of Section\n66, the punishment that is imposable on the offender of rape under\nthe prevailing law,\n(h) In the case of the commission of any act referred to in clause (i) or\n(k) of sub-section (3) of Section 66, a fine of up to one hundred fifty\nthousand rupees and imprisonment for up to fifteen years.\n(4) A person who incites another person, attempts or abets to commit any\nof the acts set forth in sub-sections (1), (2) and (3) shall be liable to the punishment\nof fine and imprisonment imposable on the principal offender.\n(5) A person who does any act, in contravention of this Act or the rules\nframed under this Act, other than that contained in this Section, shall be liable to\na fine of up to fifty thousand rupees or imprisonment for up to one year, or both\npunishments, according to the degree of the offence.\n(6) If a person who has been punished once under this Act repeats such act,\nhe or she shall be liable to an additional punishment of twenty-five per cent of the\npunishment imposable pursuant to this Section.\n(7) Notwithstanding anything contained elsewhere in this Section, if an act\nreferred to in sub-section (3) is also deemed to be an offence under any other\nprevailing law, no provision of this Section shall prevent the instituting of a\nseparate case against, and imposing of punishment on, the offender for such\noffence under that law, and, if the punishment imposable on him or her under the\nprevailing law for the commission of any act in contravention of this Act exceeds\nthe punishment set forth in this Section, he or she liable to the punishment\naccordingly.\n(8) If any one establishes or operates a children’s home, child correction\nhome, observation chamber, rehabilitation centre or temporary protection service\ncentre without obtaining permission under this Act, the Ministry may shut down\nsuch children’s home, child correction home, observation chamber, rehabilitation\ncentre or temporary protection service centre and impose a fine of up to one\nhundred thousand rupees on the person and organization involved, and may\nproceed with other additional actions in accordance with the prevailing law.\n35\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "73", "title": "Compensation: (1) The juvenile court shall cause the recovery of such a", "content": "reasonable compensation in lump sum or instalments from the offender to the\nvictim child that is not less than the amount of fine imposed on the offender\ncommitting the offence against the child under this Act and the prevailing law,\nhaving regard to, inter alia, the loss caused to the education, and physical and\nmental health, development and family of the child victim.\n(2) In cases where the amount of fine cannot be recovered pursuant to sub-\nsection (1) from the offender or if the Juvenile Court is of the opinion that such\namount of fine, even if recovered, is negligible or inadequate in comparison to the\noffence against the child, the Juvenile Court shall cause the payment of a\nreasonable amount of compensation to the child victim from the Child Fund\nreferred to in Section 63.\n(3) If the child victim dies before receiving the amount of compensation\nreferred to in sub-section (1), such amount shall be provided to his or her father,\nmother or, if they are not available, to other family member or guardian.\n(4) If it is necessary to immediately carry out medical treatment of or\nprovide compensation or any kind of relief to the child victim of an offence against\nthe child under the prevailing law or offence against the child, interim\ncompensation shall be provided in accordance with the prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "74", "title": "Statute of limitation: (1) In relation to any offence under Section 66, a case has", "content": "to be filed within the statute of limitation, if any, specified in the prevailing law,\nand, if not so specified, within one year of the date of the commission of that\noffence.\n(2) In cases where no case has been filed pursuant to sub-section (1),\nnotwithstanding anything contained in the prevailing law, the statute of limitation\nfor filing the case with respect to the offence against the child shall continue to\nexist until one year after such a child has attained the age of eighteen years.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "75", "title": "Power to try cases: The Juvenile Court shall have the power to try and dispose of", "content": "cases punishable under the sub-sections other than sub-section (8) of Section 72.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "76", "title": "Government of Nepal to be plaintiff: In the cases under Section 66, the", "content": "Government of Nepal shall be the plaintiff, and such cases shall be deemed to be\nincluded in Schedule 1 of the National Criminal Procedure (Code) Act 2017.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 10", "title": "Chapter 10", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "77", "title": "Duties of the child: (1) It shall be the duty of every child to respect his or her", "content": "father, mother, guardian, other family members, teachers and social service\nproviders and obey the advice, suggestion, guidance and instruction given by\nthem, taking into consideration of his or her best interests.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "78", "title": "To maintain confidentiality: (1) No person shall publish or broadcast through", "content": "print or electronic media any details that discloses the identity of a child concerned\nwith a case that is sub judice in the Juvenile Court.\n(2) No person shall broadcast information or news through any\ncommunication media by disclosing the identity of a child victim of an offence\nagainst children.\n(3) The police, government attorney or Juvenile Court shall make\narrangements for maintaining records of child victims of the offences against\nchildren, without disclosing their names and identity.\n(4) The investigation authority, government attorney and Juvenile Court\nshall keep the identity of children in conflict with law confidential. Copies of\ndocuments related to such charge shall not be given to any person other than the\nconcerned police and government attorney’s office, Juvenile Court, the child\nconcerned, family members, guardian, legal practitioner of the concerned child\nand Central and District Child Justice Committee.\n(5) Notwithstanding anything contained elsewhere in this Section, the\ndetails related to the child may be published or broadcast as follows, in the\nfollowing circumstance:\n(a) If publishing or broadcasting the details relating to the children in\nconflict with law does not adversely affect the interests of such\nchildren, such details, with the permission of the Juvenile Court,\n(b) Data on the children in conflict with law may be published with the\npermission of the concerned agency, for any study or research, with\nthe disclosure of their age or gender, without disclosing their names,\nsurnames, personal details and addresses.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "79", "title": "Provisions relating to probation authority: (1) The Government of Nepal shall", "content": "appoint the probation authority in each district to carry out, inter alia, investigation\ninto the concerned case, inspection of the observation chamber, diversion, and\n37\nwww.lawcommission.gov.np\npreparation of reports on the status of implementation of the orders by the Juvenile\nCourt, in close contact with the children accused of offense.\n(2) Until the probation authority is appointed, the Government of Nepal\nmay designate any authority of the Government of Nepal to act as the probation\nauthority.\n(3) The functions, duties, powers and terms and conditions of service of,\nand other provisions relating to, the probation authority shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "80", "title": "Case not to be tried and disposed of without legal practitioner: (1)", "content": "Notwithstanding anything contained in the prevailing law, the Juvenile Court shall\nnot try and dispose of a case involving a child charged with committing an offense\nuntil a legal practitioner is appointed for defending the child.\n(2) In cases where no legal practitioner has been appointed on behalf of a\nchild accused of an offense, the concerned Juvenile Court shall make arrangements\nto make service available from a paid legal practitioner or any other interested\nlegal practitioner.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "81", "title": "Appeal: (1) In the case of not being satisfied with the decision made by the", "content": "Juvenile Court or by the Ministry pursuant to sub-section (8) of Section 72, an\nappeal may be filed in the concerned High Court within thirty-five days of such a\ndecision.\n(2) Notwithstanding anything contained in sub-section (1) and in the\nprevailing law, no appeal shall be admissible against a decision of the Juvenile\nCourt that acquits a child, other than in the circumstances affecting justice because\nof erroneous interpretation of law, wrong use of precedent or non-admission of an\nadmissible evidence or admission of a non-admissible evidence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "82", "title": "Priority to be given in proceedings of case: Priority shall be given to the", "content": "proceedings, trial and disposal of cases involving children either as plaintiff or\ndefendant in the courts other than the Juvenile Court.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "83", "title": "Basis for determining children’s age: While determining the age of a child, the", "content": "following matters shall be taken as the basis:\n(a) The date of birth recorded in the child’s birth registration issued by\nthe hospital,\n(b) If the date of birth referred to in clause (a) is not available, the date\nof birth recorded in the child’s birth registration certificate issued\nby the Local Registrar’s Office,\n38\nwww.lawcommission.gov.np\n(c) If the certificate referred to in clause (b) is not available, the date of\nbirth recorded in the child’s school character certificate or the date\nof birth recorded at the time of child’s admission to the school,\n(d) If the certificate referred to in clause (b) or the date of birth is not\navailable, the date recorded in the certificate of age issued by the\nhospital,\n(e) If the certificate referred to in clause (d) is not available, the age\nrecorded in the Janmakundali (birth chart), Cheena (horoscope),\nnotes, or the age disclosed by the father, mother, guardian or any\nother family member of the child or similar other relevant evidence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "84", "title": "Act to prevail: The matters contained in this Act shall be governed by this Act", "content": "and the other matters shall be governed by the prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "85", "title": "Power to frame rules: The Government of Nepal may frame necessary rules in", "content": "order to implement the objectives of this Act.\nProvided that the Supreme Court may frame the rules relating to procedures\non the dispensation of juvenile justice.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "86", "title": "Power to frame guidelines and operational procedures: (1) The Ministry may", "content": "frame guidelines and operational procedures, as necessary, subject to this Act and\nthe Rules framed under this Act.\n(2) The Supreme Court may frame juvenile justice procedures or guidelines\nsubject to this Act or the Rules framed under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "87", "title": "Amendment, repeal and saving: (1) The following clause (a) shall be substituted", "content": "for clause (a) of sub-section (1) of Section 4 of the Births, Deaths and Other\nPersonal Events (Registration) Act, 2033 (1976):\n“(a) Information on birth and death by the father, mother, any family\nmember or guardian,”\n(2) The Act Relating to Children, 2048 (1992) is hereby repealed.\n(3) Any acts done and actions taken pursuant to the Act Relating to\nChildren, 2048 (1992) shall be deemed to have been done and taken under this\nAct.\n39", "children": []}]}]$CODEx4d1e6fd74e$::jsonb,$CODExbd9608d3e4$Act Relating to Children, 2075.pdf$CODExbd9608d3e4$) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, original_title=EXCLUDED.original_title, document_type=EXCLUDED.document_type, year_bs=EXCLUDED.year_bs, year_ad=EXCLUDED.year_ad, total_pages=EXCLUDED.total_pages, nodes=EXCLUDED.nodes, source_filename=EXCLUDED.source_filename;
